const q = await tools["API-query-data-source"]({data_source_id:"00000000-0000-4000-8000-0000e0000001", page_size:100});
const hits = q.results.filter(p=>p.properties.Sprint?.select?.name==="S4" && p.properties.Responsable.people.some(x=>x.name==="Diego Paz") && p.properties.Estado.status?.name!=="Hecha");
let done=0;
for (const p of hits) {
  const ids = p.properties.Responsable.people.map(x=>x.id===DIEGO?BRUNO:x.id);
  const uniq=[...new Set(ids)].map(id=>({object:"user",id}));
  await tools["API-patch-page"]({page_id:p.id, properties:{Responsable:{people:uniq}}});
  done++;
}
const chk = await tools["API-query-data-source"]({data_source_id:"00000000-0000-4000-8000-0000e0000001", page_size:100});
console.log(done, JSON.stringify(chk.results.filter(p=>hits.some(h=>h.id===p.id)).map(p=>p.properties.Responsable.people.map(x=>x.name))));

